import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const n="/assets/861db5454e637cf5.BpB55mm2.png",r="/assets/0712cc9777d17156.i4KJBbLq.png",o="/assets/d0cb01335ede0236.hc-ETXAs.png",l="/assets/efc4cc901f0e1d63.Duf7NRbo.png",d="/assets/ce43dddb41af5cca.odAjd8QW.png",h="/assets/fa5c31cbba7f8079.YWzNVUW3.png",p="/assets/3119ee99548c5ac7.DaTQNc4u.png",c="/assets/83666dd29bb88747.C1pwWxoz.png",u="/assets/6a31e1c005a9452f.DYuH8KJ5.png",m="/assets/07c2b69aa594d0d9.D5ncjEXz.png",f="/assets/b436d92f95ba9e51.B0nzPfm-.png",g="/assets/42dfe263f25bbe54.CTLK1XFK.png",b="/assets/cef53288604fdb11.hWADJfJu.png",k="/assets/d447b5fee231cc28.BA5EZlX4.png",v="/assets/d4852966170674ea.DwTQ7GyV.png",C=JSON.parse('{"title":"Mounting and Expanding Linux System Disk","description":"","frontmatter":{"title":"Mounting and Expanding Linux System Disk"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/mounting-and-expanding-linux-system-disk.md","filePath":"operations-knowledge-base/operating-system/linux/mounting-and-expanding-linux-system-disk.md","lastUpdated":1794311093000}'),y={name:"operations-knowledge-base/operating-system/linux/mounting-and-expanding-linux-system-disk.md"};function x(w,e,_,q,P,F){return a(),i("div",null,[...e[0]||(e[0]=[s('<p>For scenarios where additional hard disks need to be added to a machine and manually mounted and expanded Data is invaluable, so ensure that data is backed up before performing any formatting operations.</p><p><strong>1. Mounting a New Partition</strong></p><ul><li>#lsblk #View the currently recognized disks in the system and take note of the new disk&#39;s name.</li></ul><p><img src="'+n+'" alt=""></p><ul><li>#fdisk    /dev/sdb    #Start partitioning.</li></ul><p>n - Create a new partition - Partition type: Press Enter (default) - Partition number: Press Enter (default) - Start sector: Press Enter (default) - Last sector: + Partition size</p><p>p - View partition table</p><p>w - Save and exit</p><p><img src="'+r+'" alt=""></p><ul><li><h1 id="lsblk-or-fdisk-l-view-partition-results" tabindex="-1">lsblk or fdisk -l - View partition results <a class="header-anchor" href="#lsblk-or-fdisk-l-view-partition-results" aria-label="Permalink to &quot;lsblk or fdisk -l - View partition results&quot;">​</a></h1></li></ul><p><img src="'+o+'" alt=""></p><ul><li>parted /dev/device_file</li><li>mklabel - Create a partition table</li><li>gpt - We should use the gpt partition table format for disks larger than 2TB</li><li>yes - Confirm that the existing data on the disk will be destroyed</li><li>mkpart - Perform the partition operation, specifying the partition name, file system, and the start and end positions of the partition</li><li>print - Print the partition information</li></ul><p><img src="'+l+'" alt=""></p><ul><li><h1 id="mkfs-xfs-f-dev-sdb1-format-the-file-system-as-xfs" tabindex="-1">mkfs.xfs -f /dev/sdb1 #Format the file system as XFS <a class="header-anchor" href="#mkfs-xfs-f-dev-sdb1-format-the-file-system-as-xfs" aria-label="Permalink to &quot;mkfs.xfs   -f   /dev/sdb1    #Format the file system as XFS&quot;">​</a></h1></li></ul><p><img src="'+d+'" alt=""></p><ul><li><h1 id="blkid-dev-sdb1-view-the-file-system-type-and-uuid" tabindex="-1">blkid /dev/sdb1 #View the file system type and UUID <a class="header-anchor" href="#blkid-dev-sdb1-view-the-file-system-type-and-uuid" aria-label="Permalink to &quot;blkid   /dev/sdb1      #View the file system type and UUID&quot;">​</a></h1></li></ul><p><img src="'+h+'" alt="Figure 3"></p><ul><li><h1 id="mkdir-mypart-create-a-mount-point" tabindex="-1">mkdir /mypart #Create a mount point. <a class="header-anchor" href="#mkdir-mypart-create-a-mount-point" aria-label="Permalink to &quot;mkdir  /mypart  #Create a mount point.&quot;">​</a></h1></li><li><h1 id="vim-etc-fstab-set-up-automatic-mounting-at-startup" tabindex="-1">vim /etc/fstab #Set up automatic mounting at startup. <a class="header-anchor" href="#vim-etc-fstab-set-up-automatic-mounting-at-startup" aria-label="Permalink to &quot;vim    /etc/fstab   #Set up automatic mounting at startup.&quot;">​</a></h1></li></ul><p>UUID=[File system UUID] /mypart xfs defaults 0 0</p><p><img src="'+p+'" alt="Figure 4"></p><ul><li><h1 id="mount-a-refresh-or-reload-the-etc-fstab-file" tabindex="-1">mount -a # Refresh or reload the /etc/fstab file <a class="header-anchor" href="#mount-a-refresh-or-reload-the-etc-fstab-file" aria-label="Permalink to &quot;mount   -a       # Refresh or reload the /etc/fstab file&quot;">​</a></h1></li></ul><p>Check if the /etc/fstab file has the correct format for automatic mounting during startup.</p><p>Check if the entries in /etc/fstab are written correctly,</p><ul><li><h1 id="df-h" tabindex="-1">df -h <a class="header-anchor" href="#df-h" aria-label="Permalink to &quot;df  -h&quot;">​</a></h1></li></ul><p><img src="'+c+'" alt="Figure 5"></p><p>After executing the reboot command, if there are no issues with the mounted points, it indicates that automatic mounting during startup is effective.</p><p><strong>2. Expanding existing partitions</strong></p><p>Here, we will take /www partition as an example for expanding:</p><p>First, verify if your hard disk is part of an LVM volume group. If your machine does not have an LVM volume group, then your hard disk does not support expansion.</p><ul><li><h1 id="lsblk-check-the-hard-disks-recognized-by-the-current-system-and-take-note-of-their-current-capacities" tabindex="-1">lsblk #Check the hard disks recognized by the current system and take note of their current capacities. <a class="header-anchor" href="#lsblk-check-the-hard-disks-recognized-by-the-current-system-and-take-note-of-their-current-capacities" aria-label="Permalink to &quot;lsblk  #Check the hard disks recognized by the current system and take note of their current capacities.&quot;">​</a></h1></li></ul><p><img src="'+u+'" alt="Figure 1"></p><ul><li><h1 id="pvdisplay-check-the-volume-group-names" tabindex="-1">pvdisplay #Check the volume group names. <a class="header-anchor" href="#pvdisplay-check-the-volume-group-names" aria-label="Permalink to &quot;pvdisplay   #Check the volume group names.&quot;">​</a></h1></li></ul><p><img src="'+m+'" alt="Figure 3"></p><ul><li>#parted /dev/sda print #Display the current disk partitions and check if the format is GPT. Remember the current parameters.</li></ul><p><img src="'+f+'" alt="Figure 4"></p><p>If you encounter the error shown in the screenshot, follow the system prompt and enter &quot;Fix&quot;. The system will automatically set the capacity of the expanded disk partition to GPT.</p><p><img src="'+g+'" alt="378061be-5fb1-4c27-9c01-14063d62badd"></p><p>mkpart primary 1075MB 250GB #The first 1075MB represents the End capacity mentioned in the second step, and the second 250GB represents the capacity of Disk /dev/sdb.</p><p>After completing the process, you can exit by typing &quot;quit&quot;.</p><ul><li><h1 id="df-h-you-can-view-the-partition-results-and-here-we-can-see-that-the-partitioning-has-been-successful" tabindex="-1">df -h #You can view the partition results, and here we can see that the partitioning has been successful. <a class="header-anchor" href="#df-h-you-can-view-the-partition-results-and-here-we-can-see-that-the-partitioning-has-been-successful" aria-label="Permalink to &quot;df -h        #You can view the partition results, and here we can see that the partitioning has been successful.&quot;">​</a></h1></li></ul><p><img src="'+b+'" alt="Figure 5"></p><p>Add the partition to the volume group</p><ul><li><h1 id="pvcreate-dev-sda2-add-the-partition-to-the-physical-volume" tabindex="-1">pvcreate /dev/sda2 #Add the partition to the physical volume <a class="header-anchor" href="#pvcreate-dev-sda2-add-the-partition-to-the-physical-volume" aria-label="Permalink to &quot;pvcreate   /dev/sda2  #Add the partition to the physical volume&quot;">​</a></h1></li><li><h1 id="vgextend-vg-dev-sda2-extend-the-volume-group-vg" tabindex="-1">vgextend vg /dev/sda2 #Extend the volume group (VG) <a class="header-anchor" href="#vgextend-vg-dev-sda2-extend-the-volume-group-vg" aria-label="Permalink to &quot;vgextend   vg   /dev/sda2  #Extend the volume group (VG)&quot;">​</a></h1></li><li><h1 id="lvextend-l-100-free-dev-vg-www-extend-the-logical-volume-lv" tabindex="-1">lvextend -l +100%free /dev/vg/www #Extend the logical volume (LV) <a class="header-anchor" href="#lvextend-l-100-free-dev-vg-www-extend-the-logical-volume-lv" aria-label="Permalink to &quot;lvextend  -l  +100%free  /dev/vg/www  #Extend the logical volume (LV)&quot;">​</a></h1></li></ul><p>Format the file system</p><ul><li><h1 id="blkid-check-the-file-system-of-the-partition-to-be-expanded" tabindex="-1">blkid #Check the file system of the partition to be expanded. <a class="header-anchor" href="#blkid-check-the-file-system-of-the-partition-to-be-expanded" aria-label="Permalink to &quot;blkid  #Check the file system of the partition to be expanded.&quot;">​</a></h1></li></ul><p><img src="'+k+'" alt="Figure 6"></p><p>The command &quot;xfs_growfs&quot; is used to expand the XFS file system, while &quot;resize2fs&quot; is used to expand the ext4 file system.</p><ul><li><p>#resize2fs /dev/vg/www #Format as ext4</p></li><li><h1 id="df-h-here-we-can-see-that-the-expansion-has-been-successful" tabindex="-1">df -h #Here we can see that the expansion has been successful. <a class="header-anchor" href="#df-h-here-we-can-see-that-the-expansion-has-been-successful" aria-label="Permalink to &quot;df -h  #Here we can see that the expansion has been successful.&quot;">​</a></h1></li></ul><p><img src="'+v+'" alt="Figure 7"></p><h2 id="reboot-finally-restart-the-system-and-confirm-again" tabindex="-1">reboot Finally, restart the system and confirm again <a class="header-anchor" href="#reboot-finally-restart-the-system-and-confirm-again" aria-label="Permalink to &quot;reboot  Finally, restart the system and confirm again&quot;">​</a></h2>',50)])])}const E=t(y,[["render",x]]);export{C as __pageData,E as default};
